unitsize(2mm);
defaultpen(linewidth(0.7pt)+fontsize(12pt));

pair H=(0,0), A=(0,10), B=(10,10), C=(10,3), G=(10,0), E=(13,3), F=(13,0);
pair D=extension(A,F,B,G);

draw(A--B--G--H--cycle);
fill(D--C--E--F--cycle, black);
draw(A--F);
draw(G--F--E--C);

label("$A$",A,NW);
label("$H$",H,SW);
label("$B$",B,NE);
label("$C$",C,NE);
label("$G$",G,S);
label("$D$",D,WSW);
label("$E$",E,NE);
label("$F$",F,SE);
